    cin >> count;
    string line;
    getline(cin, line);
    int line_number = 1;
    while (count--) {
        getline(cin, line);
        ++line_number;
        cout << "chart " << line.substr(6) << '\n';
        vector<Definition> definitions;
        while (getline(cin, line)) {
            ++line_number;
            if (line == "RUN") break;
            definitions.push_back(parse_definition(line, line_number));
        }
        Chart chart;
        bool valid = chart.define(definitions);
        while (getline(cin, line)) {
            ++line_number;
            if (line == "END") break;
            if (valid) chart.script(line);
        }
    }
